namespace Gordic.Ada.WebClient {

    var gcontent = Decorators.gcontent;

    @gcontent

    export class GAdminTypyCiselnikuDetail extends GContentBase implements IGContent {

        title = "Detail typu číselníku"; //aby se dalo přistoupit z breadcrumbs, je nastaveno zde místo v C#
        taskId = "actDetailtypCis"; // označení položky v taskListu

        private globals = Gordic.Ada.Globals.GAdaGlobals;

        public modelTypCis: Gordic.Ada.Interface.GSrvscspDto;
        private RezimNova: Boolean;

        //---------------------------------------------------------------
        // Inicializace formuláře
        onContentReady() {

            var that = this;
            that.title = (that.RezimNova == true ? "Nový typ číselníku" : "Detail typu číselníku");

            that.actions.addRange({                                                                                     // přidání akcí

                actOK: {
                    caption: "Uložit",                                                                                      // OK
                    icon: "gi-save",                                                                                           // ikona 
                    visible: true,                                                                                      // vždy viditelné
                    enabled: that.globals.Param_Administrace_TypCis!,
                    run: function () {
                        that.closing(true) 
                    }
                },
                actZrusit: {
                    caption: "Zrušit",                                                                                  // popis
                    icon: "gi-window-close",                                                                            // ikona 
                    visible: true,                                                                                      // vždy viditelné
                    enabled: true,                                                                                      // vždy spustitelné
                    run: function () {
                        that.closing(false) 
                    }
                }
            });

            this.actions.addRange({
                actSeznamPod: {
                    caption: "Seznam hodnot" + that.modelTypCis.nazev_skp,
                    align: "opposite",
                    visible: that.RezimNova == false,
                    favorite: true,
                    icon: "gi-plus",
                    run: () => {

                        var l_oDiv = that.navigate(
                            "Gordic.Ada.WebClient.GAdminSrvsskp",
                            {
                                id: 'DetailSKP2#',
                                Konfigurace: that.modelTypCis,
                                Ixs_Csp: that.modelTypCis.ixs_csp
                            });
                        return;
                    }
                }
            });


            //*******************************************************
            // P ř i d á v á n í   a k c í   d o   m e n u   b a r u
            this.menuBar(this.actions.createBar(["actOK*", "actZrusit*"], ["actSeznamPod*"]));

            this.commandBar([
                { action: that.actions.actOK, favorite: true, primary: true },                                                         // Ok
                { action: that.actions.actZrusit, favorite: true },                                                     // Zrušit
            ]);


            // *****************************
            //    Formulář tabu
            var AdmindetailtypCisForm = new Gordic.Forms.Form({ name: "AdminDetailTypCis", layoutDescriptor: "L1M1S1 LMS-3-6-3" })
                .addField("gdummyfield", "w-h", { model: "ixs_csp",name: "ixs_csp" })
//                .addRow("Typ číselníku").addField("gstringbox", "w-12", { disabled: true, name: "ixs_csp" })
                .addRow("Název").addField("gstringbox", "w-12", { disabled: false, name: "nazev", validators: [new Gordic.Validators.Required(), new Gordic.Validators.Length({ min: 1, max: 250, message: "Překročena maximální možná délka" })] })
                .addRow("Zkratka").addField("gstringbox", "w-12", { disabled: false, name: "zkratka" })
                .addRow("Poznámka").addField("gstringbox", "w-12", { disabled: false, name: "poznamka" })
                .addRow("Aktivita").addField("gselectbox", Gordic.Prefabs.Select.gincakt(), { name: "aktivita", dropdown: true, model: "model.aktivita = value.aktivita", serverFilters: { aktivita: [100, 500] }, validators: [new Gordic.Validators.Required()] })
               .addSection("1. úroveň")
                .addRow("Název").addField("gstringbox", "w-12", { disabled: false, name: "nazev_skp", validators: [new Gordic.Validators.Required(), new Gordic.Validators.Length({ min: 1, max: 250, message: "Překročena maximální možná délka" })] })
                .addRow("Zkratka").addField("gstringbox", "w-12", { disabled: false, name: "zkratka_skp", validators: [new Gordic.Validators.Required(), new Gordic.Validators.Length({ min: 1, max: 50, message: "Překročena maximální možná délka" })] })
                .addRow("Délka").addField("gnumberbox", "w-12", { disabled: false, name: "delka_skp", validators: [new Gordic.Validators.Required(), new Gordic.Validators.Range({ min: 1, max: 20, message: "Překročena maximální možná délka" })] })
               .addSection("2. úroveň")
                .addRow("Název").addField("gstringbox", "w-12", { disabled: false, name: "nazev_psk", validators: [new Gordic.Validators.Length({ min: 0, max: 250, message: "Překročena maximální možná délka" })] })
                .addRow("Zkratka").addField("gstringbox", "w-12", { disabled: false, name: "zkratka_psk", validators: [new Gordic.Validators.Length({ min: 0, max: 50, message: "Překročena maximální možná délka" })] })
                .addRow("Délka").addField("gnumberbox", "w-12", { disabled: false, name: "delka_psk", validators: [new Gordic.Validators.Range({ min: 0, max: 20, message: "Překročena maximální možná délka" })] })
                .addSection("Poslední změna")
                .addRow("Provedl").addField("gselectbox", Gordic.Prefabs.Select.ginszmp(), { name: "zmenu_prov", dropdown: true, model: "model.zmenu_prov = value.ixs_zmp", disabled: true })
                .addRow("Provedena").addField("gdatebox", "w-12", {  name: "dat_zmena", disabled: true })
                ;


            $("<div class='js-detailPSP'>").appendTo(that.element).gform("createFrom", AdmindetailtypCisForm ).findFields().gfield("model", "apply", that.modelTypCis);
            if (!that.globals.Param_Administrace_TypCis!) {
                that.findFields().gfield("option", "disabled", true);
            }

            // nastav flag podle validatoru
            Utils.Form.markRequired(this.findFields());

         };

        //---------------------------------------------------------------
        // Zavírání formuláře
        closing( provest ) {
            if (provest == true) {
                var $cDiv = $(this.contentDiv);
                //this.contentDiv.showFlash({ label: 'Ukladam akci ' + cislo });
                if ($cDiv.findForms().gform("isValid", true)) {
                    //var dto = {};
                    $cDiv.findFields().gfield("model", "collect", this.modelTypCis);
                    $cDiv.findFields().gfield("confirm");

                    this.close({ data: this.modelTypCis });                                  // při zavírání posílanám zpět objekt
                }
            }
            else {
                this.close({ data: null });                                  // při zavírání posílanám zpět objekt
            }
        }
    }
}